{
  "Q1": {
    "q1a_rule": {
      "verdict": "yes",
      "rationale": "Gives 2026-15665, 91 FR 49178–49227, Aug. 3, 2026, effective Sept. 2, 2026, docket OPM-2025-0107, RIN 3206-AO86."
    },
    "q1b_nprm": {
      "verdict": "yes",
      "rationale": "Gives 2026-04377, 91 FR 10904–10934, published March 5, 2026."
    },
    "q1c_first": {
      "verdict": "yes",
      "rationale": "Gives 2026-17335, Aug. 25, 2026, effective Sept. 2, 2026, correcting amendatory instructions, cross-references, terminology and typographical errors."
    },
    "q1c_second": {
      "verdict": "yes",
      "rationale": "Gives 2026-18800, published and effective Sept. 15, 2026, restoring 330.602(1)(i)-(ii) of the CTAP 'displaced' definition."
    },
    "q1d_applicability": {
      "verdict": "yes",
      "rationale": "States notice issuance before Sept. 2 keeps the earlier rules and on/after Sept. 2 applies the amended rules, citing the DATES line and implementation discussion at 91 FR 49178 and 49206–49207."
    },
    "q1e_appeals": {
      "verdict": "yes",
      "rationale": "Lists 2026-15666, effective Sept. 2, in force subject to the notice transition, revising 351.802(a)(6), 351.807(e), the authority citation and subpart I."
    },
    "q1e_leave": {
      "verdict": "yes",
      "rationale": "Lists 2026-21320, says it rewrites 351.806, effective Nov. 18, 2026, and says it is adopted but not effective/in force on Nov. 14."
    },
    "q1e_senior": {
      "verdict": "yes",
      "rationale": "Lists 2026-21316, says it revises the 351.203 rating-of-record definition and amends 351.503(a)(1), (b)(2), (b)(3), effective Nov. 18, 2026, not yet effective."
    },
    "q1_cite": {
      "verdict": "no",
      "rationale": "Citations to documents, FR pages and CFR provisions are abundant throughout."
    },
    "q1_fab": {
      "verdict": "no",
      "rationale": "No invented document number, FR citation, quotation or unsupported attributed provision appears; the described corrections and rules are real."
    }
  },
  "Q2": {
    "q2a_abbott": {
      "verdict": "yes",
      "rationale": "Abbott: 7 + 5 + 5 = 17 performance credit, 0 veterans' points, total 17."
    },
    "q2a_bianchi": {
      "verdict": "yes",
      "rationale": "Bianchi: 5 + 0 + 3 = 8, Level 2 scored as 0, plus 5 veterans' points = 13."
    },
    "q2a_castillo": {
      "verdict": "yes",
      "rationale": "Castillo: 17 performance credit and 0 veterans' points, with the 351.504(b) retired-member analysis."
    },
    "q2a_dalton": {
      "verdict": "yes",
      "rationale": "Dalton: two ratings, proxy (7 + 0)/2 = 3.5, performance credit 10.5, plus 3 = 13.5."
    },
    "q2a_eze": {
      "verdict": "yes",
      "rationale": "Eze: 5 + 5 + 5 = 15, no veterans' points, total 15, and placed in tenure subgroup II."
    },
    "q2a_fontaine": {
      "verdict": "yes",
      "rationale": "Fontaine: one rating, 5 x 3 = 15, total 15."
    },
    "q2b_order": {
      "verdict": "yes",
      "rationale": "Order is Abbott, Castillo, Fontaine, Eze, Dalton, Bianchi; both ties are explained (Abbott's earlier SCD over Castillo; subgroup I over II for Fontaine over Eze)."
    },
    "q2b_released": {
      "verdict": "yes",
      "rationale": "Says Dalton and Bianchi are released."
    },
    "q2c_old": {
      "verdict": "yes",
      "rationale": "Says Bianchi would have stood above Abbott because the earlier system ranked tenure group, then veterans' subgroup AD/A/B, then service as augmented by performance credit, citing 91 FR 49186, 49198."
    },
    "q2d_records": {
      "verdict": "yes",
      "rationale": "Says a noticed employee may inspect the complete retention register, including all listed employees' names and relevant retention information, plus other-position registers affecting the level or assignment rights, subject to disclosure law."
    },
    "q2_cite": {
      "verdict": "no",
      "rationale": "The answer cites CFR provisions, FR pages and the final rule throughout."
    },
    "q2_fab": {
      "verdict": "no",
      "rationale": "No invented source or unsupported quotation/provision is apparent."
    }
  },
  "Q3": {
    "q3a_case_a": {
      "verdict": "yes",
      "rationale": "Case A: not preference eligible, 0 points, subgroup B, because a 22-year length-of-service retirement fails 351.504(b)(1)-(3) and (b)(4) is not met."
    },
    "q3a_case_b": {
      "verdict": "yes",
      "rationale": "Case B: not preference eligible, 0 points, subgroup B; the 40% disability does not satisfy (b)(1), the 21-year length retirement fails (b)(2), and (b)(4) also requires one of (b)(1)-(3)."
    },
    "q3a_case_c": {
      "verdict": "yes",
      "rationale": "Case C: preference eligible, +5, subgroup AD, under (b)(1)(i), (b)(2), (b)(4) and (a)(1)."
    },
    "q3a_case_d": {
      "verdict": "yes",
      "rationale": "Case D: not preference eligible, 0 points, subgroup B; 24-year length retirement meets none of (b)(1)-(3)."
    },
    "q3a_case_e": {
      "verdict": "yes",
      "rationale": "Case E: preference eligible, +3, subgroup A, because retired pay is not based on 20+ years under (b)(2), below major, and the disability is under 30%."
    },
    "q3b_scd_a": {
      "verdict": "yes",
      "rationale": "Employee A's SCD is Sept. 7, 2008, crediting only the two campaign years under 351.505(b)(2)(i)."
    },
    "q3b_scd_c": {
      "verdict": "yes",
      "rationale": "Employee C's SCD is Sept. 7, 1996, crediting all 14 years because he is a preference eligible under 351.505(b)(2)(ii)."
    },
    "q3c_labels": {
      "verdict": "yes",
      "rationale": "Says AD/A/B identify preference status and point augmentation, not an independent ranking step; augmented performance credit, then tenure subgroup, then SCD control."
    },
    "q3_cite": {
      "verdict": "no",
      "rationale": "The answer cites the relevant CFR paragraphs and FR pages."
    },
    "q3_fab": {
      "verdict": "no",
      "rationale": "No fabricated source or unsupported attribution is apparent."
    }
  },
  "Q4": {
    "q4a_farah": {
      "verdict": "yes",
      "rationale": "Uses Level 5 (7), Level 3 (3), Level 3 (3), total 13."
    },
    "q4b_cutoff_date": {
      "verdict": "yes",
      "rationale": "Computes Sept. 3, 2026 minus 45 days = July 20, 2026."
    },
    "q4b_credit": {
      "verdict": "yes",
      "rationale": "Excludes the Aug. 10, 2026 rating and uses 3 + 3 + 5 = 11."
    },
    "q4c_not_on_record": {
      "verdict": "yes",
      "rationale": "Correctly says the rating cannot be used if Aug. 15 was when it first became available to the retention-register office, but allows use if it was otherwise available by the cutoff, matching 351.503(c)(2)-(3)."
    },
    "q4d_gina": {
      "verdict": "yes",
      "rationale": "Excludes the Aug. 15, 2022 rating, uses 5 and 3, proxy 4, total 12."
    },
    "q4e_modal": {
      "verdict": "yes",
      "rationale": "Says credit must be based on the modal rating for the applicable summary-level pattern under 351.503(f)(1), not zero or the one/two-rating formula."
    },
    "q4e_flag": {
      "verdict": "yes",
      "rationale": "Flags that neither the modal rating nor the incorporated modal-rating definition is printed in the 2026 documents, so no numerical credit can be computed."
    },
    "q4_cite": {
      "verdict": "no",
      "rationale": "CFR and FR citations are supplied throughout."
    },
    "q4_fab": {
      "verdict": "no",
      "rationale": "No invented authority or fabricated quotation appears."
    }
  },
  "Q5": {
    "q5a_i_rules": {
      "verdict": "yes",
      "rationale": "Says the earlier rules govern the Aug. 28 noticed RIF because notice issuance precedes Sept. 2, despite the Oct. 27 effective date."
    },
    "q5a_i_result": {
      "verdict": "yes",
      "rationale": "Applies 12 years for three Level 3 ratings and 20 for three Level 5 ratings, giving Lee 1986 and Park 1999; Lee retained, Park released."
    },
    "q5a_ii": {
      "verdict": "yes",
      "rationale": "Says the amended rules apply to Sept. 2, 2026, with Park 21 and Lee 9, so Lee is released."
    },
    "q5a_iii": {
      "verdict": "yes",
      "rationale": "Says Lee is released on the Sept. 3 notice under the amended rules."
    },
    "q5b_no_recalc": {
      "verdict": "yes",
      "rationale": "Says no recalculation because 351.805(b) makes an amended notice solely moving the effective date not a new specific notice for 351.507."
    },
    "q5c_version": {
      "verdict": "yes",
      "rationale": "Rule version is fixed by the agency's issuance of the RIF notice, against Sept. 2, 2026, citing the DATES/implementation discussion."
    },
    "q5c_window": {
      "verdict": "yes",
      "rationale": "Four-year window ends at issuance of the RIF notices, or the agency cutoff date if used, under 351.503(c)(1)-(2)."
    },
    "q5c_standing": {
      "verdict": "yes",
      "rationale": "Tenure subgroup and retention standing are fixed by employee receipt of the specific RIF notice under 351.502 and 351.507(a)."
    },
    "q5_cite": {
      "verdict": "no",
      "rationale": "The answer cites the relevant CFR provisions and FR pages."
    },
    "q5_fab": {
      "verdict": "no",
      "rationale": "No invented source or fabricated attribution is apparent."
    }
  },
  "Q6": {
    "q6a_reach": {
      "verdict": "yes",
      "rationale": "Treats positions 1–3 as within reach and rules out 4 (four-grade reduction), 5 (higher-standing holder), 6 (different schedule) and 7 (different competitive area)."
    },
    "q6a_offer": {
      "verdict": "yes",
      "rationale": "Says the agency must offer position 1, Ellis's GS-12, as the least reduction in representative rate."
    },
    "q6b_five": {
      "verdict": "yes",
      "rationale": "Says the limit becomes five grades, so position 4/GS-9 is also within reach, while the offer remains position 1."
    },
    "q6c_level1": {
      "verdict": "yes",
      "rationale": "Says a Level 1 rating gives no assignment right under 351.701(a), which requires Level 2 or higher."
    },
    "q6d_excepted": {
      "verdict": "yes",
      "rationale": "Says excepted-service employees have no automatic 351.701 right; an agency may adopt provisions under 351.705(a)."
    },
    "q6e_level2": {
      "verdict": "yes",
      "rationale": "Says the former restriction on Level 2 employees taking positions held by higher-rated employees was removed."
    },
    "q6e_bump": {
      "verdict": "yes",
      "rationale": "Says separate bumping and retreating tests were replaced by the unified assignment right to a lower-standing employee's position."
    },
    "q6_cite": {
      "verdict": "no",
      "rationale": "The answer cites 351.701, 351.705(a) and 91 FR 49204."
    },
    "q6_fab": {
      "verdict": "no",
      "rationale": "No invented source or unsupported quotation is apparent."
    }
  },
  "Q7": {
    "q7a_mspb": {
      "verdict": "yes",
      "rationale": "Concludes MSPB because the notice was issued Aug. 31, before Sept. 2, while flagging the Board's inconsistent language."
    },
    "q7a_board_rule": {
      "verdict": "yes",
      "rationale": "Cites FR Doc. 2026-16456, 91 FR 51997–51998, saying MSPB will accept pre-effective-date-notice cases."
    },
    "q7b_opm": {
      "verdict": "yes",
      "rationale": "Says the appeal goes to OPM under 351.901(a)."
    },
    "q7b_count": {
      "verdict": "yes",
      "rationale": "Counts day 1 as Dec. 19, 2026, day 30 as Jan. 17, 2027, notes that is a Sunday and Jan. 18 is a holiday."
    },
    "q7b_date": {
      "verdict": "yes",
      "rationale": "Gives Tuesday, Jan. 19, 2027, at 11:59 p.m. Eastern Time as the deadline."
    },
    "q7b_efile": {
      "verdict": "yes",
      "rationale": "Says filing must normally be through OPM's electronic filing system and gives the 11:59 p.m. ET rule."
    },
    "q7c_burden": {
      "verdict": "yes",
      "rationale": "States the preponderance burden and the required showings of noncompliance and prejudice under 351.901(b)."
    },
    "q7c_hearing": {
      "verdict": "yes",
      "rationale": "Says no hearing as of right; review is on the written record unless OPM finds a hearing necessary and efficient under 351.905(c)."
    },
    "q7d_text": {
      "verdict": "yes",
      "rationale": "Says 351.901(c)(1)-(2) bars raising a RIF action under a negotiated grievance procedure or grievance arbitration."
    },
    "q7d_flag": {
      "verdict": "yes",
      "rationale": "Reports the preamble on existing CBAs: no retroactive invalidation, bargaining constrained on renegotiation, and existing-agreement disputes left to the chapter 71 forum."
    },
    "q7e_court": {
      "verdict": "yes",
      "rationale": "Says the rule bars judicial review under 351.901(c)(4) and provides no further appeal from OPM's final decision under 351.909(e)."
    },
    "q7f_tolling": {
      "verdict": "yes",
      "rationale": "Applies 351.902(b)(3), gives 30 days after the collateral decision becomes final, and computes Friday, April 9, 2027."
    },
    "q7g_where": {
      "verdict": "yes",
      "rationale": "Locates the applicability rule in the DATES line at 91 FR 49230 and the preamble at 49248, noting 351.901 does not contain a separate applicability note."
    },
    "q7_cite": {
      "verdict": "no",
      "rationale": "The answer cites the relevant CFR provisions and FR pages throughout."
    },
    "q7_fab": {
      "verdict": "no",
      "rationale": "The odd-looking E8-15622 citation is a real FR document and does mention the Martin Luther King Jr. holiday and 5 U.S.C. 6103; no fabrication."
    }
  },
  "Q8": {
    "q8a_adopted": {
      "verdict": "yes",
      "rationale": "Identifies 2026-21320 as rewriting 351.806, effective Nov. 18, 2026, and says it is adopted but not in force on Nov. 14."
    },
    "q8a_new_text": {
      "verdict": "yes",
      "rationale": "Gives the duty-status default, administrative leave for all or part of the notice period when appropriate and consistent with part 630 subpart N, and retention of the emergency rule."
    },
    "q8a_today": {
      "verdict": "yes",
      "rationale": "Gives the current 'when possible ... active duty status' text, citing FR Doc. 95-643 at 60 FR 2679 and the 2026 rulemaking descriptions."
    },
    "q8b_consent": {
      "verdict": "yes",
      "rationale": "Says consent is not required, citing 630.1403(c)(10) and the preamble's explanation that leave may be provided with or without consent."
    },
    "q8b_cap": {
      "verdict": "yes",
      "rationale": "Says the adopted RIF provisions state no separate numerical day cap and permit leave for all or part of the notice period."
    },
    "q8b_12wk": {
      "verdict": "yes",
      "rationale": "Discusses the reported 12-week workforce-realignment limit and notes that the clauses expressly mentioning governmentwide/agency limits are 630.1403(c)(9) and (11), not the RIF use in (c)(10)."
    },
    "q8b_flag": {
      "verdict": "yes",
      "rationale": "Flags that the text does not clearly say whether the 12-week limit reaches RIF-specific leave under (c)(10)."
    },
    "q8c_guidance": {
      "verdict": "yes",
      "rationale": "Says OPM relied on its existing Agency Policy Template, CPM 2025-12, which already permitted leave between notice and separation."
    },
    "q8d_no_effect": {
      "verdict": "yes",
      "rationale": "Says administrative leave does not alter retention standing, notice rights or appeal rights; the provisions concern paid non-duty status only."
    },
    "q8_cite": {
      "verdict": "no",
      "rationale": "The answer cites CFR provisions and FR pages throughout."
    },
    "q8_fab": {
      "verdict": "no",
      "rationale": "No invented source or fabricated quotation is apparent."
    }
  },
  "Q9": {
    "q9_s1": {
      "verdict": "yes",
      "rationale": "Finds step 1 noncompliant: 57 days is within 90 days and 351.402(c) required submission of the area description and bona fide organizational justification to OPM for advance approval."
    },
    "q9_s3": {
      "verdict": "yes",
      "rationale": "Finds step 3 noncompliant: supervisory probation is not an initial probationary period; career-tenured Ortiz is a competing employee and had to be ranked."
    },
    "q9_s4": {
      "verdict": "yes",
      "rationale": "Finds step 4 noncompliant: cutoff was Sept. 13, 2026, so the Oct. 2 rating cannot be used, and selective use also violates uniform application."
    },
    "q9_s5": {
      "verdict": "yes",
      "rationale": "Finds step 5 noncompliant: proxy is (7 + 5)/2 = 6, so credit is 7 + 5 + 6 = 18, not 15."
    },
    "q9_s6": {
      "verdict": "yes",
      "rationale": "Finds step 6 noncompliant: 351.503(d) allows enhancement only under a system whose highest level is 3, not a five-level pattern; advance policy does not cure it."
    },
    "q9_s8": {
      "verdict": "yes",
      "rationale": "Finds step 8 noncompliant under 351.602(a), which bars retaining an employee on a limited temporary or term promotion while releasing a competing employee."
    },
    "q9_s10": {
      "verdict": "yes",
      "rationale": "Finds step 10 noncompliant because 351.702(a)(4) bars an assessment consisting solely of or principally relying on an automated self-assessment."
    },
    "q9_s11": {
      "verdict": "yes",
      "rationale": "Finds step 11 noncompliant because 351.608(a)(3) bars stacking exceptions; the agency may use only the single exception giving the longest retention."
    },
    "q9_s12": {
      "verdict": "yes",
      "rationale": "Finds step 12 noncompliant because Sept. 2, 2026 and later notices appeal to OPM, not MSPB; the 30-day period itself is correct."
    },
    "q9_ok": {
      "verdict": "yes",
      "rationale": "Says steps 2, 7 and 9 are all in order and gives provisions for each: 351.202(d), 351.601(c), and 351.702(a)(4)(v)."
    },
    "q9_false2": {
      "verdict": "no",
      "rationale": "It correctly treats step 2 as in order."
    },
    "q9_false7": {
      "verdict": "no",
      "rationale": "It correctly treats step 7 as in order."
    },
    "q9_false9": {
      "verdict": "no",
      "rationale": "It treats step 9 as in order on the assessment-waiver point."
    },
    "q9_cite": {
      "verdict": "no",
      "rationale": "The answer cites the relevant CFR paragraphs and FR pages for each step."
    },
    "q9_fab": {
      "verdict": "no",
      "rationale": "No invented source or unsupported quotation is apparent."
    }
  },
  "Q10": {
    "q10a_gap": {
      "verdict": "yes",
      "rationale": "Says paragraph (1) contained only the introductory 'who:' text on Sept. 10 because instruction 11 revised the paragraph and deleted (1)(i)-(ii) when the rule took effect Sept. 2."
    },
    "q10b_doc": {
      "verdict": "yes",
      "rationale": "Identifies 2026-18800, 91 FR 58363, published and effective Sept. 15, 2026, restoring both subparagraphs."
    },
    "q10b_reason": {
      "verdict": "yes",
      "rationale": "Gives good cause under 5 U.S.C. 553(b)(B), no substantive change, restoration of pre-Sept. 2 text OPM had not proposed to remove, and effective-on-publication under 553(d)(3)."
    },
    "q10c_lower": {
      "verdict": "yes",
      "rationale": "Says declining a lower-representative-rate offer leaves her 'displaced' under (1)(i), which requires an offer with the same schedule type and at least the same representative rate."
    },
    "q10c_same": {
      "verdict": "yes",
      "rationale": "Says declining the same-representative-rate, same-schedule offer means she is no longer 'displaced' under (1)(i)."
    },
    "q10_cite": {
      "verdict": "no",
      "rationale": "The answer cites the relevant FR documents and CFR provision."
    },
    "q10_fab": {
      "verdict": "no",
      "rationale": "No invented source or fabricated attribution is apparent."
    }
  },
  "Q11": {
    "q11_valid_10": {
      "verdict": "yes",
      "rationale": "Counted valid pieces, in submission order: authority citation (1); 202(d) introductory language (1); 202(d)(1)(ii),(2)(i)-(ii) (3); 202(d)(2)(iii) (1); 202(d)(3)-(4) (2); 351.203 furlough trim (1); 351.203 rating-of-record 430.208 cross-reference (1); 351.203 restoration-protected definition (1); 351.204 (1); 351.302(d) (1); 351.402(c) (1); 351.502 issue-vs-receipt date (1); 351.502(a)(3) temporary/term (1); 351.503(a)(1) Level 2 label + 430.208 cross-reference (2); 351.503(d)/(e)(2) 91 FR 41521 phrase (1); 351.504(a) should/must (1); 351.505(b)(2) cross-reference (1); 351.506(c) their/the employee's (1); 351.506(d) saved-access sentence (1); 351.604 not finalized (1); 351.605 restructure/notice/assignment (3); 351.606(a) (1); 351.608(a)(2) subpart E/F (1); 351.701(a) Minimally Successful/Satisfactory (1); 351.702(a)(4)(iii) (1); 351.702(a)(4)(v) (1); 351.802(a) introductory text (1); 351.802(a)(2) veterans' preference subgroup (1); 351.802(a)(3) information on access (1); 351.805(b) (1). Total = 36. Not counted: the 351.203 'of this part' row, because the key excludes a final-text error later corrected back to the proposed wording; the separate 351.503(d)/(e)(1) 430.208(d)->(e) row duplicates the same 430.208 cross-reference update counted in 351.503(a)(1); the listed 2026-17335 correction items are corrections, not proposal-to-final differences."
    },
    "q11_valid_16": {
      "verdict": "yes",
      "rationale": "Same total of 36 valid pieces as q11_valid_10; meets the 16 threshold."
    },
    "q11_valid_22": {
      "verdict": "yes",
      "rationale": "Same total of 36 valid pieces; meets the 22 threshold."
    },
    "q11_valid_28": {
      "verdict": "yes",
      "rationale": "Same total of 36 valid pieces; meets the 28 threshold."
    },
    "q11_valid_34": {
      "verdict": "yes",
      "rationale": "Same total of 36 valid pieces; meets the 34 threshold."
    },
    "q11_deep": {
      "verdict": "yes",
      "rationale": "Covers at least six deep items: 351.502 issue-vs-receipt, Level 2 Minimally Successful/Satisfactory, 351.504(a) should/must, 351.505(b)(2) cross-reference, 351.506(c)/(d), 351.702(a)(4)(iii)/(v), 351.802(a)(2)/(a)(3), 351.302(d), 351.608(a)(2), the 91 FR 41521 phrase, and the authority citation."
    },
    "q11_cite": {
      "verdict": "no",
      "rationale": "The table gives proposed and final FR pages throughout."
    },
    "q11_fab": {
      "verdict": "no",
      "rationale": "No invented source or fabricated quotation is apparent; the cited differences were largely confirmed by the key."
    }
  },
  "Q12": {
    "q12_quinn": {
      "verdict": "yes",
      "rationale": "Says Quinn is an initial-probation career-conditional employee, not a competing employee, not ranked, and may be retained under 351.202(d)."
    },
    "q12_ab": {
      "verdict": "yes",
      "rationale": "Alvarez 7 + 7 + 5 = 19, no points; Brandt 3 + 5 + 0 = 8 plus 5 = 13."
    },
    "q12_chen": {
      "verdict": "yes",
      "rationale": "Excludes the Sept. 30, 2022 Level 2, uses Level 5 and Level 4 with proxy 6, and reaches 18."
    },
    "q12_dube": {
      "verdict": "yes",
      "rationale": "Two ratings, proxy 5, performance credit 15, plus 3 = 18."
    },
    "q12_estrada": {
      "verdict": "yes",
      "rationale": "Uses 5 + 3 + 5 = 13, plus 3 = 16, and excludes the Oct. 20, 2026 rating."
    },
    "q12_farouk_score": {
      "verdict": "yes",
      "rationale": "One rating, 3 x 3 = 9, no veterans' points, lowest on the register."
    },
    "q12_tie": {
      "verdict": "yes",
      "rationale": "Order Alvarez 19, Chen 18, Dube 18, Estrada 16, Brandt 13, Farouk 9; Chen ahead of Dube because subgroup I precedes II at equal total."
    },
